import React from "react";
import BigBangImage from "./bigBang.png";
import vid from "./boom.mp4";
import SubHeading from "../../../Components/Heading/SubHeading";
import Paragraphs from "../../../Components/Heading/Paragraphs";

function Section2() {
  const title = (
    <h1 className=" text-yellow-500 relative text-3xl font-poppins mb-10"></h1>
  );

  const paraText = "";

  return (
    <>
      <div className="  w-full h-screen p-10 md:flex md:p-1 ">
        <div className=" text-center p-3 text-xl md:w-1/2 md:pt-40 ">
          <SubHeading text="Formation and Early Evolution" />
          <Paragraphs
            text=""
          />
          <div className=" justify-start flex">
            <button className=" text-white bg-purple-950 rounded-md w-3/12 h-12  ">
              Explore More
            </button>
          </div>
        </div>
        <div className=" md:w-1/2  ">
          <video
            src={vid}
            loop
            autoPlay
            muted
            className="md:h-screen w-full "
          ></video>
          {/* <img src={BigBangImage} alt="" srcset="" className=" md:h-screen" /> */}
        </div>
      </div>
    </>
  );
}

export default Section2;
